import{_ as t,c as o,o as r,ae as s}from"./chunks/framework.D4V3g9Ih.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"_parts/bem-block.md","filePath":"docs/_parts/bem-block.md"}'),n={name:"_parts/bem-block.md"};function i(a,e,c,l,p,m){return r(),o("div",null,[...e[0]||(e[0]=[s('<details class="details custom-block"><summary>🧱 How the BEM block is determined</summary><p>Some BEM linters — like <a href="https://github.com/postcss/postcss-bem-linter" target="_blank" rel="noreferrer">postcss-bem-linter</a> — require you to define the block name explicitly using a comment (<code>/** @define the-component */</code>) or derive it from the filename via configuration.</p><p>This plugin takes a different, much simpler approach:</p><hr><blockquote><p><strong>The first base block declaration in the file determines the component&#39;s block.</strong><strong>If none exists, the block name is derived from the first element or modifier.</strong></p></blockquote><hr><p>✅ <strong>Why this is enough</strong> <br> In a component-oriented architecture, there is rarely a reason to define more than one block per file. This convention keeps block detection consistent across rules without additional annotations or configuration.</p><hr><p>❓ <strong>What if you need more control?</strong> <br> If your project uses a different structure, this assumption may not work well.</p><p>This plugin doesn&#39;t currently support custom block resolution logic or in-file annotations — mostly because there&#39;s little evidence it&#39;s needed. <br> But if you have a real use case — feel free to open an issue and describe your use case.</p></details>',1)])])}const f=t(n,[["render",i]]);export{u as __pageData,f as default};
